const titles = {home:'给故事一个温柔的家',stories:'每一篇故事，都值得被珍藏',characters:'那些住进故事里的人',series:'为不同的故事宇宙建立秩序',music:'让每个故事拥有自己的旋律',themes:'设计属于你的阅读世界',settings:'让收藏安心留在身边'};

function uid(prefix='id'){ return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`; }
function esc(s=''){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function toast(s){ const el=$('#toast'); if(!el)return; el.textContent=s; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),2800); }
function dateLabel(t){ return new Date(t||Date.now()).toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'}); }
function parseTags(s){ return String(s||'').split(/[,，\n]/).map(x=>x.trim()).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i); }
function seriesName(id){ return state.series.find(s=>s.id===id)?.name||'未分类'; }
function storyOrder(a,b){ return (Number(a.order)||Number(a.createdAt)||0)-(Number(b.order)||Number(b.createdAt)||0); }
function storyNo(story){ const list=state.stories.filter(s=>(s.seriesId||'')===(story.seriesId||'')).sort(storyOrder); const i=list.findIndex(s=>s.id===story.id); return Math.max(1,i+1); }
function safeFilename(s, fallback='export'){ return (String(s||fallback).replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').trim().slice(0,100)||fallback); }
function clone(o){ return JSON.parse(JSON.stringify(o)); }
function normalizeState(data){
  const merged={...structuredClone(seed),...(data||{})};
  merged.settings={...structuredClone(seed.settings),...(data?.settings||{})};
  merged.themeDrafts=(data?.themeDrafts&&typeof data.themeDrafts==='object')?data.themeDrafts:{};
  merged.player={...structuredClone(seed.player),...(data?.player||{})};merged.player.queueTrackIds=Array.isArray(merged.player.queueTrackIds)?merged.player.queueTrackIds:[];merged.player.position=Math.max(0,Number(merged.player.position)||0);merged.player.isPlaying=false;
  for(const key of ['series','characters','stories','tracks','playlists','themes']) if(!Array.isArray(merged[key])) merged[key]=[];
  merged.series.forEach((s,i)=>{s.order??=i+1;s.description??='';s.music=normalizeMusic(s.music);s.themeId??='';});
  merged.characters.forEach(c=>{c.storyIds??=[];c.description??='';c.storyIds=Array.isArray(c.storyIds)?c.storyIds:[];c.music=normalizeMusic(c.music);});
  merged.stories.forEach((s,i)=>{
    s.characterIds=Array.isArray(s.characterIds)?s.characterIds:[];s.tags=Array.isArray(s.tags)?s.tags:[];s.raw??=s.body||'';s.body??=s.raw||'';s.sourceFormat??=detectFormat(s.raw,'text');s.bodyFormat??=detectFormat(s.body,'text');s.history=Array.isArray(s.history)?s.history.slice(-1):[];s.order??=i+1;s.readProgress=Math.max(0,Math.min(100,Number(s.readProgress)||0));s.readScrollY=Number(s.readScrollY)||0;s.coverMediaId??='';s.themeId??='';s.music=normalizeMusic(s.music);s.updatedAt??=s.createdAt||Date.now();s.createdAt??=s.updatedAt;
    // Migrate the previous prototype's semantics without making an empty default look like a custom override.
    if(s.music.disabled===true) s.music.override='off'; else if(s.music.override==null) s.music.override=(s.music.playlistId||(s.music.trackIds||[]).length)?'custom':'inherit';
    if(s.music.autoPlay===true) s.music.autoPlay='on'; if(s.music.autoPlay===false) s.music.autoPlay='off';
    // Local fields must never defeat an explicit inheritance choice. Keep the chosen character selector.
    if(s.music.override==='inherit'){s.music.playlistId='';s.music.trackIds=[];}
    s.music.inheritCharacterId??='';
  });
  merged.tracks.forEach(t=>{t.tags=Array.isArray(t.tags)?t.tags:parseTags(t.tags);t.mediaId??='';t.createdAt??=Date.now();t.mediaOmitted=!!t.mediaOmitted&&!t.mediaId;});
  merged.player.queueTrackIds=merged.player.queueTrackIds.filter(id=>merged.tracks.some(t=>t.id===id));
  if(merged.player.trackId&&!merged.tracks.some(t=>t.id===merged.player.trackId)){merged.player.trackId='';merged.player.isPlaying=false;merged.player.position=0;}
  if(merged.player.storyId&&!merged.stories.some(s=>s.id===merged.player.storyId))merged.player.storyId='';
  merged.playlists.forEach(p=>{p.trackIds=Array.isArray(p.trackIds)?p.trackIds.filter(id=>merged.tracks.some(t=>t.id===id)):[];p.coverMediaId??='';});
  merged.themes.forEach(t=>{t.type??='reading';t.history=Array.isArray(t.history)?t.history.slice(-1):[];t.css??='';});
  return merged;
}
function normalizeMusic(m){
  const v={override:'inherit',mode:'fixed',playlistId:'',trackIds:[],loop:'inherit',autoPlay:'inherit',inheritCharacterId:'',...(m||{})};
  v.trackIds=Array.isArray(v.trackIds)?v.trackIds:[];
  // Migrate older saved configurations that had a playlist/track selection but no explicit override.
  if(!m?.override&&(v.playlistId||v.trackIds.length))v.override='custom';
  if(v.disabled===true && !m?.override) v.override='off';
  if(v.autoPlay===true) v.autoPlay='on'; if(v.autoPlay===false) v.autoPlay='off';
  // Stale local IDs must not leak through an explicit inherit/off setting.
  if(v.override==='inherit'||v.override==='off'){v.playlistId='';v.trackIds=[];}
  return v;
}
function openDB(){
  if(dbPromise)return dbPromise;
  dbPromise=new Promise((resolve,reject)=>{
    if(!('indexedDB' in window)){reject(new Error('当前浏览器不支持 IndexedDB'));return;}
    const req=indexedDB.open(DB_NAME,DB_VERSION);
    req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('kv'))d.createObjectStore('kv',{keyPath:'key'});if(!d.objectStoreNames.contains('media'))d.createObjectStore('media',{keyPath:'id'});};
    req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('数据库打开失败'));
  });
  return dbPromise;
}
async function dbGet(store,key){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction(store,'readonly').objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbPut(store,value){const d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||new Error('保存失败'));tx.onabort=()=>reject(tx.error||new Error('保存已中止'));});}
async function dbDelete(store,key){const d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);});}
async function dbGetAll(store){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction(store,'readonly').objectStore(store).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error);});}
async function loadState(){
  try{
    const stored=await dbGet('kv','state');
    if(stored?.value){state=normalizeState(stored.value);return;}
    let legacy=null;try{legacy=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}
    state=normalizeState(legacy||seed);await dbPut('kv',{key:'state',value:state,updatedAt:Date.now()});
    if(legacy)toast('已迁移旧版收藏数据；旧版临时音频引用无法自动恢复。');
  }catch(e){
    try{state=normalizeState(JSON.parse(localStorage.getItem(KEY)||'null')||seed);}catch{state=normalizeState(seed);}
    toast('持久化数据库不可用，当前仅能尝试使用旧版本地存储。请及时导出备份。');
  }
}
let persistChain=Promise.resolve();
function persist(msg='已自动保存'){
  const snapshot=clone(state);
  const write=persistChain.catch(()=>{}).then(async()=>{await dbPut('kv',{key:'state',value:snapshot,updatedAt:Date.now()});});
  persistChain=write;write.catch(e=>{console.error('Persist failed',e);toast('保存失败：'+(e?.message||'存储不可用')+'。请立即导出备份。');});
  persistChain.then(()=>{try{localStorage.setItem(KEY,JSON.stringify(snapshot));}catch{/* IndexedDB is authoritative; localStorage is only a migration fallback. */}}).catch(()=>{});
  if(msg)toast(msg);return persistChain;
}
async function saveMedia(blob, name='', type=''){if(!(blob instanceof Blob))throw new Error('媒体文件无效');const id=uid('media');await dbPut('media',{id,blob,name:name||blob.name||'media',type:type||blob.type||'application/octet-stream',size:blob.size,createdAt:Date.now()});return id;}
async function putMediaWithId(id,blob,name='',type=''){const cached=mediaUrlCache.get(id);if(cached){URL.revokeObjectURL(cached);mediaUrlCache.delete(id);}await dbPut('media',{id,blob,name,type:type||blob.type||'application/octet-stream',size:blob.size,createdAt:Date.now()});}
async function readMedia(id){if(!id)return null;const item=await dbGet('media',id);return item?.blob||null;}
async function deleteMedia(id){if(!id)return;try{await dbDelete('media',id);const u=mediaUrlCache.get(id);if(u)URL.revokeObjectURL(u);mediaUrlCache.delete(id);}catch(e){console.warn('Could not delete media',e);}}
async function getMediaURL(id){if(!id)return '';if(mediaUrlCache.has(id))return mediaUrlCache.get(id);const blob=await readMedia(id);if(!blob)return '';const url=URL.createObjectURL(blob);mediaUrlCache.set(id,url);return url;}
async function hydrateMediaImages(root=document){for(const img of $$('img[data-media-id]',root)){try{const url=await getMediaURL(img.dataset.mediaId);if(url)img.src=url;else img.classList.add('media-missing');}catch{img.classList.add('media-missing');}}}

function card(story){
  const n=String(storyNo(story)).padStart(2,'0');
  const cover=story.coverMediaId?`<img data-media-id="${esc(story.coverMediaId)}" alt="${esc(story.title)}封面" loading="lazy">`:'';
  return `<article class="story-card card-story ${state.settings.layout==='text'?'text-card':''}" data-story-card="${esc(story.id)}"><div class="cover card-cover">${cover}<span class="cover-number">${esc(seriesName(story.seriesId))} · ${n}</span></div><div class="story-info"><div class="series">${esc(seriesName(story.seriesId))} · 第 ${storyNo(story)} 章</div><h3 class="story-title">${esc(story.title)}</h3><p class="summary">${esc(story.summary||'尚未添加简介。打开故事，开始阅读。')}</p>${tagsHTML(story.tags||[])}<div class="card-footer"><div class="progress-info" style="flex:1"><span class="muted">阅读进度 ${story.readProgress||0}%</span><div class="progress"><span style="width:${story.readProgress||0}%"></span></div></div><div class="small-actions"><button data-action="read" data-id="${esc(story.id)}" title="阅读">阅读 ↗</button><button data-action="edit" data-id="${esc(story.id)}" title="编辑">编辑</button><button data-action="music" data-id="${esc(story.id)}" title="配乐">♫</button><button data-action="delete-story" data-id="${esc(story.id)}" title="删除番外">删除</button></div></div></div></article>`;
}
function tagsHTML(tags=[]){return `<div class="tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`;}
function headerSection(title,sub,action=''){return `<div class="section-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>${action}</div>`;}
function render(){
  const content=$('#pageContent');$('#pageTitle').textContent=titles[currentPage]||titles.home;
  $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));
  const renderers={home:renderHome,stories:renderStories,characters:renderCharacters,series:renderSeries,music:renderMusic,themes:renderThemes,settings:renderSettings};
  content.innerHTML=(renderers[currentPage]||renderHome)();bindContent();bindActionButtons(content);hydrateMediaImages(content);applyThemeStyles(readerId?state.stories.find(s=>s.id===readerId):null);
}
function renderHome(){return `<section class="hero app-hero"><div class="hero-copy"><div class="eyebrow">A LITTLE UNIVERSE OF STORIES</div><h2>把喜欢的故事，<br>好好收藏起来。</h2><p>番外、角色、故事系列、专属配乐与阅读主题，都可以在这里找到自己的位置。你的收藏，属于你自己的宇宙。</p><button class="button primary" data-action="new-story">＋ 收藏一篇番外</button> <button class="button secondary" data-action="goto-music">♫ 整理音乐</button></div><img class="hero-art" src="celestial-book-icon.jpg" alt="书本与星辰"></section><div class="stats"><div class="stat"><span>珍藏番外</span><strong>${state.stories.length}</strong></div><div class="stat"><span>故事系列</span><strong>${state.series.length}</strong></div><div class="stat"><span>角色档案</span><strong>${state.characters.length}</strong></div><div class="stat"><span>音乐收藏</span><strong>${state.tracks.length}</strong></div></div>${headerSection('最近收藏','继续阅读，或为故事安排新的配乐。',`<button class="text-button" data-action="goto-stories">查看全部 →</button>`)}<div class="story-grid">${state.stories.slice().sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,3).map(card).join('')}</div><div class="module-grid" style="margin-top:20px"><div class="panel"><h3>✧ 私人签名</h3><div class="signature-big">Violet196</div><p style="text-align:center">A little universe of stories</p></div><div class="panel"><h3>♫ 今日的故事配乐</h3><p>建立你的第一份歌单，把旋律与故事情绪一起珍藏。</p><button class="button secondary" data-action="goto-music">打开音乐馆</button></div></div>`;}
function renderStories(){return `${headerSection('番外收藏','支持 HTML、Markdown、TXT 文件导入与文本粘贴。',`<button class="button primary" data-action="new-story">＋ 导入番外</button>`)}<div class="toolbar"><div class="search"><input id="storySearch" placeholder="搜索标题、简介、正文、标签或角色……"></div><select id="seriesFilter" class="select"><option value="">全部系列</option>${state.series.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select><select id="sortStories" class="select"><option value="recent">最近更新</option><option value="series">按系列编号</option><option value="title">按标题</option></select><button class="pill ${state.settings.layout==='cover'?'active':''}" data-action="layout-cover">封面卡片</button><button class="pill ${state.settings.layout==='text'?'active':''}" data-action="layout-text">文字卡片</button></div><div id="storyGrid" class="story-grid">${state.stories.slice().sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).map(card).join('')||`<div class="empty"><strong>这里还空着呢</strong>导入第一篇番外，让你的故事有一个家。</div>`}</div>`;}
function renderCharacters(){return `${headerSection('角色档案','角色与番外为多对多关联；可以设置角色默认配乐。',`<button class="button primary" data-action="new-character">＋ 新建角色</button>`)}<div class="module-grid">${state.characters.map(c=>`<div class="panel"><div class="list-row"><div class="list-icon">♙</div><div class="list-main"><strong>${esc(c.name)}</strong><small>${esc(c.description||'还没有角色简介')}</small></div><button data-action="edit-character" data-id="${esc(c.id)}">编辑</button><button data-action="delete-character" data-id="${esc(c.id)}">删除</button></div><p>关联番外：${state.stories.filter(s=>(s.characterIds||[]).includes(c.id)).length} 篇</p><div class="toolbar"><button class="button secondary" data-action="character-stories" data-id="${esc(c.id)}">查看关联故事</button><button class="pill" data-action="character-music" data-id="${esc(c.id)}">默认配乐</button></div></div>`).join('')}<div class="panel"><h3>角色关联规则</h3><p>同一角色可以拥有多篇番外；一篇番外也可以关联多个角色。单篇番外优先于系列、角色与全局配乐。</p></div></div>`;}
function renderSeries(){const ordered=state.series.slice().sort((a,b)=>(a.order||0)-(b.order||0));return `${headerSection('故事系列','每个系列独立编号；可排序系列，也可拖动其中的番外排序。',`<button class="button primary" data-action="new-series">＋ 新建系列</button>`)}<div class="module-grid">${ordered.map((s,seriesIndex)=>{const stories=state.stories.filter(x=>x.seriesId===s.id).sort(storyOrder);return `<div class="panel" data-series-panel="${esc(s.id)}"><div class="list-row"><div class="list-icon">❖</div><div class="list-main"><strong>${esc(s.name)}</strong><small>${esc(s.description||`${stories.length} 篇番外 · 独立编号`)}</small></div><button data-action="move-series-up" data-id="${esc(s.id)}" aria-label="系列上移" ${seriesIndex===0?'disabled':''}>↑</button><button data-action="move-series-down" data-id="${esc(s.id)}" aria-label="系列下移" ${seriesIndex===ordered.length-1?'disabled':''}>↓</button><button data-action="edit-series" data-id="${esc(s.id)}">编辑</button><button data-action="delete-series" data-id="${esc(s.id)}">删除</button></div><p class="muted">${stories.length} 篇番外</p><label>阅读主题<select class="select" data-series-theme="${esc(s.id)}"><option value="">继承全局主题</option>${state.themes.filter(t=>t.type==='reading'||t.type==='combined').map(t=>`<option value="${esc(t.id)}" ${s.themeId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="toolbar"><button class="pill" data-action="series-music" data-id="${esc(s.id)}">系列默认配乐</button></div>${stories.map((st,i)=>`<div class="list-row sortable series-sort-row" draggable="true" data-series-story="${esc(st.id)}" data-series-id="${esc(s.id)}"><div class="list-icon">⠿ ${String(i+1).padStart(2,'0')}</div><div class="list-main"><strong>${esc(st.title)}</strong><small>第 ${i+1} 章 · ${dateLabel(st.updatedAt)}</small></div><button data-action="read" data-id="${esc(st.id)}">阅读</button><button data-action="edit" data-id="${esc(st.id)}">编辑</button></div>`).join('')||'<p class="muted">这个系列暂时还没有番外。</p>'}</div>`}).join('')}<div class="panel"><h3>编号说明</h3><p>编号属于收藏馆元数据，不覆盖正文原有标题。拖动同系列番外可自动保存新顺序；编辑番外可以将其移动到其他系列。</p></div></div>`;}
function trackRow(t){return `<div class="list-row" data-track-row="${esc(t.id)}"><div class="list-icon">♫</div><div class="list-main"><strong>${esc(t.title)}</strong><small>${esc(t.kind==='file'?'本地音频':'网络直链')} · ${esc((t.tags||[]).join('、')||'未分类')} · ${t.kind==='file'?(t.mediaOmitted?'备份中未包含音频':'已存入本机媒体库'):'在线'}</small></div><button data-action="play-track" data-id="${esc(t.id)}">试听</button><button data-action="edit-track" data-id="${esc(t.id)}">编辑</button><button data-action="add-to-playlist" data-id="${esc(t.id)}">加入歌单</button><button data-action="delete-track" data-id="${esc(t.id)}">删除</button></div>`;}
function renderMusic(){return `${headerSection('音乐馆','本地音频保存到 IndexedDB；歌单曲序、番外固定/动态配乐和继承规则独立管理。',`<button class="button primary" data-action="new-music">＋ 添加音乐</button>`)}<div class="toolbar"><div class="search"><input id="musicSearch" placeholder="搜索音乐名称或标签……"></div><button class="pill" data-action="new-playlist">＋ 新建歌单</button></div><div class="module-grid"><div class="panel"><h3>♫ 全部音乐 <span class="muted">${state.tracks.length} 首</span></h3>${state.tracks.length?state.tracks.map(trackRow).join(''):`<div class="empty"><strong>音乐馆还在等待第一首歌</strong>可以添加本地音频，或可直接播放的网络音频直链。</div>`}</div><div class="panel"><h3>自定义歌单</h3>${state.playlists.map(p=>`<div class="list-row"><div class="list-icon">${p.coverMediaId?`<img data-media-id="${esc(p.coverMediaId)}" alt="" loading="lazy">`:'♫'}</div><div class="list-main"><strong>${esc(p.name)}</strong><small>${p.trackIds.length} 首 · ${esc(p.description||'自定义歌单')}</small></div><button data-action="open-playlist" data-id="${esc(p.id)}">整理</button><button data-action="delete-playlist" data-id="${esc(p.id)}">删除</button></div>`).join('')||'<p class="muted">还没有歌单。</p>'}<p>同一首音乐可以被多个歌单引用，无需重复导入媒体文件。</p></div></div><div class="panel" style="margin-top:16px"><h3>番外配乐与默认继承</h3><p>配乐优先级：单篇番外 → 系列 → 指定角色 → 全局默认。单篇可明确关闭配乐、覆盖默认，或选择继承。</p>${state.stories.map(s=>{const eff=resolveMusicForStory(s);const label=eff.off?'明确不播放':eff.trackIds.length?`${eff.trackIds.length} 首 · ${eff.sourceLabel}`:'未配置可播放曲目';return `<div class="list-row"><div class="list-icon">▤</div><div class="list-main"><strong>${esc(s.title)}</strong><small>${esc(label)}</small></div><button data-action="music" data-id="${esc(s.id)}">设置配乐</button></div>`}).join('')}</div>`;}
function renderThemes(){const selected=state.themes.find(t=>t.id===activeThemeIdForEditor)||state.themes.find(t=>t.id===state.activeThemeId)||state.themes[0];return `${headerSection('主题设计工作室','管理 APP 主题与阅读主题；CSS 保存有上一版本快照。',`<button class="button secondary" data-action="new-theme">＋ 新建主题</button>`)}<div class="module-grid"><div class="panel"><h3>主题列表</h3>${state.themes.map(t=>`<div class="list-row"><div class="list-icon">✧</div><div class="list-main"><strong>${esc(t.name)}</strong><small>${esc(t.type)} · ${themeIsActive(t)?'当前应用':'未应用'}</small></div><button data-action="edit-theme" data-id="${esc(t.id)}">编辑</button><button data-action="apply-theme" data-id="${esc(t.id)}">应用</button><button data-action="duplicate-theme" data-id="${esc(t.id)}">复制</button><button data-action="delete-theme" data-id="${esc(t.id)}">删除</button></div>`).join('')}<p>主题类型：APP（首页/卡片/按钮等）、阅读、组合。可按故事或系列单独指定阅读主题。</p></div><div class="panel"><h3>CSS 编辑器</h3><label>选择主题<select id="themeSelect">${state.themes.map(t=>`<option value="${esc(t.id)}" ${selected?.id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>主题名称<input id="themeName" value="${esc(selected?.name||'')}"></label><label>主题类型<select id="themeType"><option value="app" ${selected?.type==='app'?'selected':''}>APP 主题</option><option value="reading" ${selected?.type==='reading'?'selected':''}>阅读主题</option><option value="combined" ${selected?.type==='combined'?'selected':''}>组合主题</option></select></label><label>导入 CSS 文件<input id="themeCSSFile" type="file" accept=".css,text/css"></label><label>CSS 源码<textarea id="themeCSS" class="theme-editor" spellcheck="false">${esc(selected?.css||'')}</textarea></label><div class="toolbar"><button class="pill" data-action="theme-undo">撤销</button><button class="pill" data-action="theme-redo">重做</button><button class="pill" data-action="theme-restore">恢复上一版本</button><button class="pill" data-action="format-css">简单格式化</button></div><div class="form-grid"><label>查找<input id="cssFind" placeholder="要查找的内容"></label><label>替换为<input id="cssReplace" placeholder="新内容"></label></div><div class="toolbar"><button class="pill" data-action="css-replace">全部替换</button><button class="button secondary" data-action="validate-css">检查 CSS</button><button class="button secondary" data-action="preview-css">预览</button><button class="button primary" data-action="save-theme">保存并应用</button><button class="pill" data-action="export-css">导出 CSS</button></div><div id="cssIssues" class="muted" aria-live="polite">基础语法检查会显示在这里。</div><div class="preview-box"><div class="story-header"><h3 class="story-title">一封未寄出的信</h3></div><p class="story-paragraph">黄昏落进窗边，纸页上还留着没有写完的句子。</p><blockquote>有些故事，值得慢慢读完。</blockquote><pre class="code-block">const littleUniverse = 'Violet196';</pre></div><div id="cssHighlight" class="css-highlight" aria-label="CSS 语法提示"></div></div></div>`;}
function renderSettings(){return `${headerSection('设置与备份','使用 IndexedDB 持久保存文本和媒体；完整备份生成包含媒体文件的 ZIP。')}<div class="module-grid"><div class="panel"><h3>阅读偏好</h3><div class="setting-row"><div><strong>首页卡片布局</strong><small>封面卡片或只显示标题版头</small></div><select id="settingLayout" class="select"><option value="cover" ${state.settings.layout==='cover'?'selected':''}>封面卡片</option><option value="text" ${state.settings.layout==='text'?'selected':''}>文字卡片</option></select></div><div class="setting-row"><div><strong>默认自动播放</strong><small>可由单篇番外、系列和角色覆盖</small></div><input type="checkbox" class="switch" id="settingAutoPlay" ${state.settings.autoPlay?'checked':''}></div><div class="setting-row"><div><strong>全局默认循环</strong><small>循环当前故事有效歌单，而非整个曲库</small></div><input type="checkbox" class="switch" id="settingLoop" ${state.settings.loop?'checked':''}></div><label>全局默认音乐歌单<select id="settingDefaultPlaylist" class="select"><option value="">不指定默认歌单</option>${state.playlists.map(p=>`<option value="${esc(p.id)}" ${state.settings.defaultPlaylistId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="setting-row"><div><strong>CSS 预览模式</strong><small>实时预览或手动预览</small></div><select id="settingPreview" class="select"><option value="manual" ${state.settings.preview==='manual'?'selected':''}>手动预览</option><option value="live" ${state.settings.preview==='live'?'selected':''}>实时预览</option></select></div><label>正文默认字号 <output id="settingFontOutput">${state.settings.fontSize}px</output><input id="settingFontSize" type="range" min="14" max="26" value="${Number(state.settings.fontSize)||17}"></label><label>正文行距 <output id="settingLineOutput">${Number(state.settings.lineHeight)||1.95}</output><input id="settingLineHeight" type="range" min="1.4" max="2.6" step="0.05" value="${Number(state.settings.lineHeight)||1.95}"></label><label>段落间距 <output id="settingParagraphOutput">${Number(state.settings.paragraphSpacing)||1.05}em</output><input id="settingParagraphSpacing" type="range" min="0.4" max="2.5" step="0.05" value="${Number(state.settings.paragraphSpacing)||1.05}"></label></div><div class="panel"><h3>数据与备份</h3><p>完整 ZIP 包含原文、阅读版本、角色、系列、标签、主题、封面以及所选媒体文件。恢复前会先检查包内数据并要求确认。</p><div class="toolbar"><button class="button primary" data-action="export-zip">导出完整 ZIP 备份</button><button class="button secondary" data-action="export-json">导出 JSON 数据</button><button class="button secondary" data-action="export-story">导出当前番外</button><button class="button secondary" data-action="export-css">导出选中主题 CSS</button></div><label class="checkline"><input id="includeAudioBackup" type="checkbox" ${state.settings.includeAudioBackup?'checked':''}>完整 ZIP 备份时包含音频文件（体积可能较大）</label><label>从 ZIP / JSON 备份恢复<input id="restoreFile" type="file" accept=".json,.zip,application/json,application/zip"></label><p class="muted">恢复采取先检查、后写入的流程，不会因为文件解析失败而覆盖当前收藏。</p><div class="setting-row"><div><strong>数据存储</strong><small>故事文本、封面和本地音频使用浏览器 IndexedDB</small></div><button class="pill" data-action="clear-data">清空数据</button></div><div class="setting-row"><div><strong>媒体占用</strong><small>可查询当前已保存媒体的大小</small></div><button class="pill" data-action="media-usage">查看占用</button></div></div></div><div class="panel" style="margin-top:16px"><h3>关于 Violet's Storybook</h3><div class="signature-big">Violet196</div><p style="text-align:center">A little universe of stories</p><p>这是可部署到 GitHub Pages 的网页原型源码，并非已编译的 Android APK。Android 后台/锁屏播放、原生文件权限和 APK 打包仍需单独实现与实机测试。</p></div>`;}
function themeIsActive(t){return state.settings.appThemeId===t.id||state.settings.readingThemeId===t.id||state.activeThemeId===t.id;}

function detectFormat(text, fallback='text'){
  const s=String(text||'').trim();if(!s)return fallback;
  if(/^<!doctype\s+html|^<html\b|^<(?:article|main|section|div|p|h[1-6]|!doctype|body)\b/i.test(s))return 'html';
  if(/(^```|^#{1,6}\s|^>\s|^[-*+]\s|^\|.+\|\s*$|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/m.test(s))return 'markdown';
  return fallback==='markdown'?'markdown':'text';
}
function safeUrl(raw, image=false){
  const s=String(raw||'').trim();if(!s||/^\s*javascript\s*:/i.test(s)||/^\s*vbscript\s*:/i.test(s)||/^\s*file\s*:/i.test(s))return '';
  if(image){if(/^data:image\/(?:png|jpeg|jpg|gif|webp);base64,/i.test(s))return s;if(/^https?:\/\//i.test(s))return s;if(/^(?:\.\.?\/|\/|[^:]+\.(?:png|jpe?g|gif|webp)(?:[?#].*)?$)/i.test(s))return s;return '';}
  if(/^(?:https?:|mailto:|tel:)/i.test(s))return s;
  if(/^(?:\.\.?\/|\/|#[^\s]*)/.test(s))return s;
  if(!/^[a-z][a-z0-9+.-]*:/i.test(s))return s;
  return '';
}
const ALLOWED_TAGS=new Set('a abbr b blockquote br caption code dd del details div dl dt em figcaption figure h1 h2 h3 h4 h5 h6 hr i img li mark ol p pre q s small span strong sub summary sup table tbody td tfoot th thead tr u ul'.split(' '));
function sanitizeInlineStyle(style){
  const allowed=new Set(['color','background-color','font-family','font-size','font-style','font-weight','line-height','letter-spacing','text-align','text-decoration','white-space','border','border-left','border-right','border-top','border-bottom','border-color','border-style','border-width','border-radius','margin','margin-left','margin-right','margin-top','margin-bottom','padding','padding-left','padding-right','padding-top','padding-bottom','max-width','width','height','vertical-align']);
  return String(style||'').split(';').map(x=>{const i=x.indexOf(':');if(i<1)return '';const k=x.slice(0,i).trim().toLowerCase(),v=x.slice(i+1).trim();if(!allowed.has(k)||/url\s*\(|expression|javascript|@import|position\s*:|z-index|behavior/i.test(v))return '';return `${k}:${v}`;}).filter(Boolean).join(';');
}
function sanitizeHtml(html){
  const doc=new DOMParser().parseFromString(String(html||''),'text/html');
  doc.querySelectorAll('script,style,iframe,frame,frameset,object,embed,applet,svg,math,form,input,button,select,textarea,link,meta,base,template,video,audio,source,track').forEach(el=>el.remove());
  for(const el of [...doc.body.querySelectorAll('*')]){
    if(!ALLOWED_TAGS.has(el.tagName.toLowerCase())){el.replaceWith(...el.childNodes);continue;}
    for(const attr of [...el.attributes]){
      const name=attr.name.toLowerCase(),value=attr.value;
      if(name.startsWith('on')||name==='srcdoc'||name==='formaction'||name==='contenteditable'||name==='autofocus'){el.removeAttribute(attr.name);continue;}
      if(name==='href'&&el.tagName==='A'){const u=safeUrl(value);if(u)el.setAttribute('href',u);else el.removeAttribute('href');continue;}
      if(name==='src'&&el.tagName==='IMG'){const u=safeUrl(value,true);if(u)el.setAttribute('src',u);else el.removeAttribute('src');continue;}
      if(name==='style'){const v=sanitizeInlineStyle(value);if(v)el.setAttribute('style',v);else el.removeAttribute('style');continue;}
      if(name==='class'){const safe=value.split(/\s+/).filter(c=>/^(?:story-|reader-|code-|language-)[a-z0-9_-]+$/i.test(c));if(safe.length)el.setAttribute('class',safe.join(' '));else el.removeAttribute('class');continue;}
      if(['title','alt','colspan','rowspan','scope','start','reversed','dir','lang'].includes(name))continue;
      el.removeAttribute(attr.name);
    }
    if(el.tagName==='A'){el.setAttribute('rel','noopener noreferrer');el.setAttribute('target','_blank');}
  }
  return doc.body.innerHTML;
}
function inlineMarkdown(text){
  let s=esc(text);
  // Protect inline code spans before other substitutions.
  const stash=[];const put=x=>{const k=`§§M${stash.length}§§`;stash.push(x);return k;};
  s=s.replace(/`([^`]+)`/g,(_,x)=>put(`<code>${x}</code>`));
  s=s.replace(/!\[([^\]]*)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)/g,(_,alt,url,title)=>{const u=safeUrl(decodeEntityForUrl(url),true);return u?put(`<img src="${esc(u)}" alt="${alt}"${title?` title="${title}"`:''}>`):alt;});
  s=s.replace(/\[([^\]]+)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)/g,(_,label,url,title)=>{const u=safeUrl(decodeEntityForUrl(url));return u?put(`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer"${title?` title="${title}"`:''}>${label}</a>`):label;});
  s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_]+)__/g,'<strong>$1</strong>').replace(/~~([^~]+)~~/g,'<del>$1</del>').replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g,'$1<em>$2</em>').replace(/(^|[^_])_([^_\n]+)_(?!_)/g,'$1<em>$2</em>');
  s=s.replace(/§§M(\d+)§§/g,(_,n)=>stash[Number(n)]||'');return s;
}
function decodeEntityForUrl(url){return String(url||'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>');}
function renderMarkdown(md){
  const lines=String(md||'').replace(/\r\n?/g,'\n').split('\n'),out=[];let i=0;
  const isSep=l=>/^\s*([-|:]\s*){2,}\|?\s*$/.test(l)&&l.includes('-');
  while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue;}
    const fence=line.match(/^\s*(```+|~~~+)(.*)$/);if(fence){const marker=fence[1][0],lang=fence[2].trim();i++;const code=[];while(i<lines.length&&!new RegExp('^\\s*'+marker+'{3,}\\s*$').test(lines[i]))code.push(lines[i++]);if(i<lines.length)i++;out.push(`<pre class="code-block"><code${lang?` class="language-${esc(lang.replace(/[^a-z0-9_-]/gi,''))}"`:''}>${esc(code.join('\n'))}</code></pre>`);continue;}
    const head=line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);if(head){out.push(`<h${head[1].length} class="story-heading">${inlineMarkdown(head[2])}</h${head[1].length}>`);i++;continue;}
    if(/^\s{0,3}(---+|___+|\*\*\*+)\s*$/.test(line)){out.push('<hr class="story-separator">');i++;continue;}
    if(i+1<lines.length&&line.includes('|')&&isSep(lines[i+1])){const heads=line.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());i+=2;const rows=[];while(i<lines.length&&lines[i].trim()&&lines[i].includes('|')){rows.push(lines[i].trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim()));i++;}out.push(`<div class="story-table-wrap"><table><thead><tr>${heads.map(x=>`<th>${inlineMarkdown(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${heads.map((_,j)=>`<td>${inlineMarkdown(r[j]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue;}
    if(/^\s*>/.test(line)){const q=[];while(i<lines.length&&/^\s*>/.test(lines[i]))q.push(lines[i++].replace(/^\s*> ?/,''));out.push(`<blockquote>${renderMarkdown(q.join('\n'))}</blockquote>`);continue;}
    if(/^\s*([-*+] |\d+\. )/.test(line)){const ordered=/^\s*\d+\. /.test(line),tag=ordered?'ol':'ul',items=[];while(i<lines.length&&/^\s*([-*+] |\d+\. )/.test(lines[i])){items.push(lines[i++].replace(/^\s*(?:[-*+] |\d+\. )/,''));}out.push(`<${tag}>${items.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</${tag}>`);continue;}
    const para=[line.trim()];i++;while(i<lines.length&&lines[i].trim()&&!/^\s*(?:#{1,6}\s|```|~~~|>|[-*+] |\d+\. |---+\s*$)/.test(lines[i])){if(i+1<lines.length&&lines[i].includes('|')&&isSep(lines[i+1]))break;para.push(lines[i++].trim());}out.push(`<p class="story-paragraph">${para.map(inlineMarkdown).join('<br>')}</p>`);
  }
  return out.join('\n');
}
function renderText(text){return String(text||'').replace(/\r\n?/g,'\n').split(/\n{2,}/).map(p=>`<p class="story-paragraph">${esc(p).replace(/\n/g,'<br>')}</p>`).join('\n');}
function renderBody(body,format='text'){if(format==='html')return sanitizeHtml(body);if(format==='markdown')return renderMarkdown(body);return renderText(body);}
function stripMarkupToText(body,format){if(format==='html'){const doc=new DOMParser().parseFromString(sanitizeHtml(body),'text/html');return doc.body.innerText||doc.body.textContent||'';}if(format==='markdown'){return String(body||'').replace(/```[\s\S]*?```/g,x=>x.replace(/^```[^\n]*\n?/,'').replace(/```$/,'')).replace(/^#{1,6}\s+/gm,'').replace(/^>\s?/gm,'').replace(/!\[([^\]]*)\]\([^)]+\)/g,'$1').replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/[*_~`]/g,'');}return String(body||'');}

function openStory(){selectedFileText='';selectedFileFormat='text';$('#storyForm').reset();$('#storySeries').innerHTML='<option value="">未分类</option>'+state.series.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('#pastePane').hidden=false;$('#filePane').hidden=true;$$('[data-import-tab]').forEach(b=>b.classList.toggle('active',b.dataset.importTab==='paste'));$('#storyDialog').showModal();}
$$('[data-import-tab]').forEach(b=>b.addEventListener('click',()=>{const file=b.dataset.importTab==='file';$('#pastePane').hidden=file;$('#filePane').hidden=!file;$$('[data-import-tab]').forEach(x=>x.classList.toggle('active',x===b));}));
$('#storyFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;selectedFileText=await f.text();selectedFileFormat=/\.html?$/i.test(f.name)?'html':/\.(?:md|markdown)$/i.test(f.name)?'markdown':'text';$('#storyForm').elements.body.value=selectedFileText;const titleInput=$('#storyForm').elements.title;if(!titleInput.value.trim())titleInput.value=f.name.replace(/\.(html?|md|markdown|txt)$/i,'');toast(`已读取 ${f.name}；可调整标题、系列、角色和封面后保存。`);});
$('#storyForm').addEventListener('submit',async e=>{
  e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const fd=new FormData(f),body=String(fd.get('body')||selectedFileText||''),title=String(fd.get('title')||'').trim();if(!title){toast('请填写番外标题');f.elements.title.focus();return;}
  try{
    let coverMediaId='';const file=$('#storyCover').files[0];if(file){if(!/^image\/(?:png|jpeg|webp|gif)$/.test(file.type))throw new Error('封面仅支持 PNG、JPG、WEBP 或 GIF');if(file.size>25*1024*1024)throw new Error('封面不能超过 25 MB');coverMediaId=await saveMedia(file,file.name,file.type);}
    const characterIds=[];parseTags(fd.get('characters')).forEach(name=>{let c=state.characters.find(c=>c.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(!c){c={id:uid('char'),name,description:'',storyIds:[],music:normalizeMusic()};state.characters.push(c);}characterIds.push(c.id);});
    const now=Date.now(),st={id:uid('story'),title,seriesId:String(fd.get('seriesId')||''),characterIds,summary:String(fd.get('summary')||'').trim(),tags:parseTags(fd.get('tags')),raw:selectedFileText||body,sourceFormat:selectedFileText?selectedFileFormat:detectFormat(body,'text'),body,bodyFormat:selectedFileText?selectedFileFormat:detectFormat(body,'text'),createdAt:now,updatedAt:now,order:now,readProgress:0,readScrollY:0,coverMediaId,history:[],music:normalizeMusic(),themeId:''};
    state.stories.push(st);state.activeStoryId=st.id;await persist('番外已保存到收藏馆');$('#storyDialog').close();selectedFileText='';f.reset();go('stories');
  }catch(err){toast('保存失败：'+(err?.message||'未知错误'));}
});

function storyPlainCharacters(st){return (st.characterIds||[]).map(id=>state.characters.find(c=>c.id===id)?.name).filter(Boolean).join(', ');}
function openEdit(st){
  editingId=st.id;const f=$('#editForm');editingFormat=st.bodyFormat||detectFormat(st.body,'text');editingMode=(editingFormat==='html'||editingFormat==='markdown')?'source':'text';
  f.elements.title.value=st.title;f.elements.summary.value=st.summary||'';f.elements.characters.value=storyPlainCharacters(st);f.elements.tags.value=(st.tags||[]).join(', ');f.elements.body.value=editingMode==='source'?st.body:stripMarkupToText(st.body,editingFormat);f.elements.mode.value=editingMode;f.elements.seriesId.innerHTML='<option value="">未分类</option>'+state.series.map(s=>`<option value="${esc(s.id)}" ${s.id===st.seriesId?'selected':''}>${esc(s.name)}</option>`).join('');
  f.elements.themeId.innerHTML='<option value="">继承系列 / 全局主题</option>'+state.themes.filter(t=>t.type==='reading'||t.type==='combined').map(t=>`<option value="${esc(t.id)}" ${t.id===st.themeId?'selected':''}>${esc(t.name)}</option>`).join('');
  $('#editCover').value='';editUndoStack=[f.elements.body.value];editRedoStack=[];$('#editModeHelp').textContent='普通文本模式编辑可读文字；切换到源码模式时会明确提示可能丢失格式。原始导入内容始终独立保留。';editInitialFingerprint=editFingerprint();$('#editDialog').showModal();
}
function switchEditMode(newMode){const f=$('#editForm'),body=f.elements.body;if(newMode===editingMode)return;if(newMode==='source'){if(!confirm('切换到源码模式后，可以编辑 Markdown / HTML。当前普通文本会被保留为内容；请注意保存格式。继续吗？')){f.elements.mode.value=editingMode;return;}const text=body.value;editingFormat='markdown';body.value=text.split(/\n{2,}/).map(x=>x.trim()).filter(Boolean).join('\n\n');editingMode='source';$('#editModeHelp').textContent='源码模式：Markdown 或 HTML。保存时自动识别格式；原始导入源码不会被覆盖。';}
  else{if(!confirm('切换到普通文本模式会移除当前源码中的排版标记；原始导入内容和上一正式版本仍会保留。继续吗？')){f.elements.mode.value=editingMode;return;}const text=body.value,fmt=detectFormat(text,editingFormat);body.value=stripMarkupToText(text,fmt);editingMode='text';editingFormat='text';$('#editModeHelp').textContent='普通文本模式：保存为段落文本，不解析源码标记。原始导入内容仍可从阅读页单独查看。';}
  editUndoStack=[body.value];editRedoStack=[];f.elements.mode.value=editingMode;saveDraft();
}
$('#editMode').addEventListener('change',e=>switchEditMode(e.target.value));
$('#editUndo').addEventListener('click',()=>{const body=$('#editForm').elements.body;if(editUndoStack.length>1){editRedoStack.push(body.value);editUndoStack.pop();body.value=editUndoStack.at(-1);saveDraft();}else toast('没有可撤销的正文编辑');});
$('#editRedo').addEventListener('click',()=>{const body=$('#editForm').elements.body;if(editRedoStack.length){const v=editRedoStack.pop();editUndoStack.push(v);body.value=v;saveDraft();}else toast('没有可重做的正文编辑');});
function editFingerprint(){const f=$('#editForm');if(!f)return '';return JSON.stringify({title:f.elements.title.value,summary:f.elements.summary.value,characters:f.elements.characters.value,tags:f.elements.tags.value,body:f.elements.body.value,mode:editingMode,format:editingFormat,seriesId:f.elements.seriesId.value,themeId:f.elements.themeId.value});}
function hasUnsavedEditChanges(){return !!editingId&&editFingerprint()!==editInitialFingerprint;}
function saveDraft(){if(!editingId)return;const f=$('#editForm');const draft={title:f.elements.title.value,summary:f.elements.summary.value,characters:f.elements.characters.value,tags:f.elements.tags.value,body:f.elements.body.value,mode:editingMode,format:editingFormat,seriesId:f.elements.seriesId.value,themeId:f.elements.themeId.value,savedAt:Date.now()};dbPut('kv',{key:'draft:'+editingId,value:draft,updatedAt:Date.now()}).catch(()=>toast('草稿保存失败，请复制正文到安全位置。'));}
$('#editForm').elements.body.addEventListener('input',()=>{if(editingId){const body=$('#editForm').elements.body.value;const last=editUndoStack[editUndoStack.length-1];if(body!==last){editUndoStack.push(body);if(editUndoStack.length>80)editUndoStack.shift();editRedoStack=[];}saveDraft();}});
['title','summary','characters','tags'].forEach(n=>$('#editForm').elements[n].addEventListener('input',saveDraft));
$('#restoreDraft').addEventListener('click',async()=>{if(!editingId)return;const d=await dbGet('kv','draft:'+editingId);if(!d?.value){toast('没有找到未保存草稿');return;}const f=$('#editForm'),v=d.value;for(const k of ['title','summary','characters','tags','body','seriesId','themeId'])if(v[k]!=null&&f.elements[k])f.elements[k].value=v[k];editingMode=v.mode||'text';editingFormat=v.format||'text';f.elements.mode.value=editingMode;editUndoStack=[f.elements.body.value];editRedoStack=[];toast('已恢复未保存草稿');});
$('#restoreHistory').addEventListener('click',()=>{const st=state.stories.find(s=>s.id===editingId),v=st?.history?.at(-1);if(!v){toast('还没有上一正式版本');return;}if(!confirm('将编辑内容替换为上一正式版本？当前输入内容会先保留在草稿中。'))return;saveDraft();const f=$('#editForm');f.elements.title.value=v.title;f.elements.body.value=v.body;f.elements.summary.value=v.summary||'';f.elements.tags.value=(v.tags||[]).join(', ');editingFormat=v.bodyFormat||'text';editingMode=editingFormat==='text'?'text':'source';f.elements.mode.value=editingMode;f.elements.body.value=editingMode==='text'?stripMarkupToText(v.body,editingFormat):v.body;editUndoStack=[f.elements.body.value];editRedoStack=[];toast('已载入上一正式版本，确认后再保存。');});
$('#clearHistory').addEventListener('click',async()=>{const st=state.stories.find(s=>s.id===editingId);if(!st||!st.history?.length){toast('没有可清除的版本历史');return;}if(!confirm('清除这篇番外的上一正式版本？此操作不可撤销。'))return;st.history=[];await persist('上一正式版本已清除');});
$('#editForm').addEventListener('submit',async e=>{
  e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const st=state.stories.find(s=>s.id===editingId);if(!st)return;const title=f.elements.title.value.trim();if(!title){toast('请填写番外标题');f.elements.title.focus();return;}
  const body=f.elements.body.value,format=editingMode==='text'?'text':detectFormat(body,editingFormat);
  try{
    st.history=[{title:st.title,body:st.body,bodyFormat:st.bodyFormat,summary:st.summary,tags:[...(st.tags||[])],seriesId:st.seriesId,themeId:st.themeId||'',characterIds:[...(st.characterIds||[])],updatedAt:st.updatedAt}].slice(-1);
    const previousSeriesId=st.seriesId;st.title=title;st.body=body;st.bodyFormat=format;st.seriesId=f.elements.seriesId.value;if(previousSeriesId!==st.seriesId){st.order=Math.max(0,...state.stories.filter(x=>x.id!==st.id&&x.seriesId===st.seriesId).map(x=>Number(x.order)||Number(x.createdAt)||0))+1000;}st.summary=f.elements.summary.value.trim();st.tags=parseTags(f.elements.tags.value);st.themeId=f.elements.themeId.value||'';st.characterIds=[];
    parseTags(f.elements.characters.value).forEach(name=>{let c=state.characters.find(c=>c.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(!c){c={id:uid('char'),name,description:'',storyIds:[],music:normalizeMusic()};state.characters.push(c);}if(!st.characterIds.includes(c.id))st.characterIds.push(c.id);});st.updatedAt=Date.now();
    const newCover=$('#editCover').files[0];if(newCover){if(!/^image\/(?:png|jpeg|webp|gif)$/.test(newCover.type))throw new Error('封面仅支持 PNG、JPG、WEBP 或 GIF');if(newCover.size>25*1024*1024)throw new Error('封面不能超过 25 MB');const old=st.coverMediaId;st.coverMediaId=await saveMedia(newCover,newCover.name,newCover.type);if(old)await deleteMedia(old);}
    await dbDelete('kv','draft:'+editingId).catch(()=>{});await persist('修改已保存；上一正式版本已备份');editInitialFingerprint=editFingerprint();$('#editDialog').close();render();if($('#readerDialog').open&&readerId===st.id)openReader(st,false);
  }catch(err){toast('保存失败：'+(err?.message||'未知错误'));}
});

function openReader(st,applyMusic=true){readerId=st.id;state.activeStoryId=st.id;$('#readerMeta').textContent=`${seriesName(st.seriesId)} · 第 ${storyNo(st)} 章`;$('#readerTitle').textContent=st.title;$('#readerBody').innerHTML=renderBody(st.body,st.bodyFormat||'text');$('#readerBody').style.fontSize=`${Number(state.settings.fontSize)||17}px`;$('#readerBody').style.lineHeight=String(Number(state.settings.lineHeight)||1.95);$('#readerBody').style.letterSpacing=`${Number(state.settings.letterSpacing)||0}px`;$('#readerBody').style.setProperty('--story-paragraph-spacing',`${Number(state.settings.paragraphSpacing)||1.05}em`);$('#readProgress').textContent=`阅读进度 ${st.readProgress||0}%`;
  if(!$('#readerDialog').open)$('#readerDialog').showModal();requestAnimationFrame(()=>{const dlg=$('#readerDialog');dlg.scrollTop=Number(st.readScrollY)||0;updateReadProgress();});applyThemeStyles(st);hydrateMediaImages($('#readerBody'));if(applyMusic)applyStoryMusic(st,true);}
function updateReadProgress(){if(!readerId)return;const st=state.stories.find(s=>s.id===readerId);if(!st)return;const dlg=$('#readerDialog'),body=$('#readerBody');if(!dlg||!body)return;const total=body.scrollHeight;if(total<=0)return;const bodyTop=body.offsetTop;const viewportBottom=dlg.scrollTop+dlg.clientHeight;const visibleIntoBody=Math.max(0,Math.min(total,viewportBottom-bodyTop));const progress=Math.max(st.readProgress||0,Math.min(100,Math.floor((visibleIntoBody/total)*100))); if(Math.abs(progress-(st.readProgress||0))>=1){st.readProgress=progress;st.readScrollY=dlg.scrollTop;$('#readProgress').textContent=`阅读进度 ${progress}%`;persist('');}}
$('#readerDialog').addEventListener('scroll',()=>{if(readerId){const st=state.stories.find(s=>s.id===readerId);if(st){st.readScrollY=$('#readerDialog').scrollTop;updateReadProgress();}}},{passive:true});
$('#closeReader').onclick=()=>{saveReaderPosition();$('#readerDialog').close();readerId=null;applyThemeStyles(null);};$('#readerDone').onclick=()=>{saveReaderPosition();$('#readerDialog').close();readerId=null;applyThemeStyles(null);};
function saveReaderPosition(){const st=state.stories.find(s=>s.id===readerId);if(st){st.readScrollY=$('#readerDialog').scrollTop;persist('');}}
$('#markRead').onclick=()=>{const st=state.stories.find(s=>s.id===readerId);if(st){st.readProgress=100;st.readScrollY=0;$('#readProgress').textContent='阅读进度 100%';persist('已标记读完');}};
$('#readerSource').onclick=()=>{const st=state.stories.find(s=>s.id===readerId);if(!st)return;$('#sourceTitle').textContent='原始导入源码';$('#sourceText').hidden=false;$('#originalRendered').hidden=true;$('#sourceText').textContent=st.raw||'';$('#sourceDialog').showModal();};
$('#readerOriginalView').onclick=()=>{const st=state.stories.find(s=>s.id===readerId);if(!st)return;$('#sourceTitle').textContent='原始内容的安全渲染';$('#sourceText').hidden=true;$('#originalRendered').hidden=false;$('#originalRendered').innerHTML=renderBody(st.raw||'',st.sourceFormat||detectFormat(st.raw,'text'));$('#sourceDialog').showModal();hydrateMediaImages($('#originalRendered'));};
$('#closeSource').onclick=()=>$('#sourceDialog').close();$('#readerEdit').onclick=()=>{const st=state.stories.find(s=>s.id===readerId);if(st)openEdit(st);};$('#readerMusic').onclick=()=>{const st=state.stories.find(s=>s.id===readerId);if(st)openMusicAssociation('story',st.id);};

function defaultMusicConfig(){return normalizeMusic({});}
function musicConfigHasChoice(m){return m&&(m.override==='custom'||m.override==='off'||m.playlistId||(m.trackIds||[]).length>0);}
function resolveConfigForStory(st){
  const own=normalizeMusic(st.music);
  if(own.override==='off'||own.disabled===true)return {...own,override:'off',sourceLabel:'单篇番外',sourceType:'story'};
  if(own.override==='custom')return {...own,sourceLabel:'单篇番外',sourceType:'story'};
  const series=state.series.find(s=>s.id===st.seriesId);if(series&&musicConfigHasChoice(normalizeMusic(series.music))){const m=normalizeMusic(series.music);return {...m,sourceLabel:'系列默认',sourceType:'series'};}
  const chars=(st.characterIds||[]).map(id=>state.characters.find(c=>c.id===id)).filter(Boolean);const preferred=chars.find(c=>c.id===own.inheritCharacterId)||chars.find(c=>musicConfigHasChoice(normalizeMusic(c.music)));
  if(preferred&&musicConfigHasChoice(normalizeMusic(preferred.music))){return {...normalizeMusic(preferred.music),sourceLabel:`角色默认：${preferred.name}`,sourceType:'character'};}
  const pl=state.playlists.find(p=>p.id===state.settings.defaultPlaylistId);if(pl)return {...defaultMusicConfig(),override:'custom',mode:'dynamic',playlistId:pl.id,sourceLabel:'全局默认',sourceType:'global',loop:state.settings.loop?'list':'none',autoPlay:state.settings.autoPlay?'on':'off'};
  return {...defaultMusicConfig(),sourceLabel:'全局默认',sourceType:'global',loop:state.settings.loop?'list':'none',autoPlay:state.settings.autoPlay?'on':'off'};
}
function resolveMusicForStory(st){const cfg=resolveConfigForStory(st);let trackIds=[];if(cfg.override==='off')return {...cfg,off:true,trackIds:[]};if(cfg.mode==='dynamic'&&cfg.playlistId){trackIds=[...(state.playlists.find(p=>p.id===cfg.playlistId)?.trackIds||[])];}else if(cfg.override==='custom'){trackIds=[...(cfg.trackIds||[])];if(!trackIds.length&&cfg.playlistId)trackIds=[...(state.playlists.find(p=>p.id===cfg.playlistId)?.trackIds||[])];}else if(cfg.playlistId){trackIds=[...(state.playlists.find(p=>p.id===cfg.playlistId)?.trackIds||[])];}
  trackIds=trackIds.filter((id,i,a)=>a.indexOf(id)===i&&state.tracks.some(t=>t.id===id));const loop=cfg.loop==='inherit'||!cfg.loop?(state.settings.loop?'list':'none'):cfg.loop;const autoPlay=cfg.autoPlay==='on'?true:cfg.autoPlay==='off'?false:!!state.settings.autoPlay;return {...cfg,trackIds,loop,autoPlay,off:false};}
function openMusicAssociation(type,id){
  const obj=type==='story'?state.stories.find(s=>s.id===id):type==='series'?state.series.find(s=>s.id===id):state.characters.find(c=>c.id===id);if(!obj)return;
  const f=$('#associationForm'),m=normalizeMusic(obj.music);f.dataset.targetType=type;f.dataset.targetId=id;$('#associationStoryName').textContent=`${type==='story'?'番外':type==='series'?'系列':'角色'}：${obj.title||obj.name}`;
  f.elements.override.value=m.override||((m.disabled)?'off':(m.playlistId||(m.trackIds||[]).length)?'custom':'inherit');f.elements.mode.value=m.mode||'fixed';
  $('#associationPlaylist').innerHTML='<option value="">不关联歌单</option>'+state.playlists.map(p=>`<option value="${esc(p.id)}" ${p.id===m.playlistId?'selected':''}>${esc(p.name)}</option>`).join('');
  f.elements.loop.value=m.loop||'inherit';f.elements.autoPlay.value=m.autoPlay==='on'||m.autoPlay===true?'on':m.autoPlay==='off'||m.autoPlay===false?'off':'inherit';
  const charLabel=$('#inheritCharacterLabel'),charSelect=$('#inheritCharacterId');charLabel.hidden=type!=='story';charSelect.innerHTML='<option value="">自动选择首个有默认配乐的角色</option>'+((type==='story'?(obj.characterIds||[]):[]).map(cid=>state.characters.find(c=>c.id===cid)).filter(Boolean).map(c=>`<option value="${esc(c.id)}" ${c.id===m.inheritCharacterId?'selected':''}>${esc(c.name)}</option>`).join(''));
  const pl=state.playlists.find(p=>p.id===m.playlistId);const selected=f.elements.override.value==='custom'&&m.mode==='fixed'?(m.trackIds.length?m.trackIds:(pl?.trackIds||[])):[];renderAssociationTracks(selected,m.trackIds.length?m.trackIds:(pl?.trackIds||[]));$('#associationDialog').showModal();
}
function renderAssociationTracks(selected=[],preferredOrder=[]){
  const root=$('#associationTrackChoices'),form=$('#associationForm'),mode=form.elements.mode.value,selectedSet=new Set(selected||[]),ordered=[...(preferredOrder||[]),...(selected||[]),...state.tracks.map(t=>t.id)].filter((id,i,a)=>a.indexOf(id)===i&&state.tracks.some(t=>t.id===id));
  root.innerHTML=`<strong>固定曲目清单（可拖动排序）</strong><p class="muted">仅在“自定义配乐 + 固定曲目清单”模式下使用。选中曲目的显示顺序就是播放顺序；动态模式直接跟随所选歌单。</p>${ordered.map(id=>{const t=state.tracks.find(x=>x.id===id);return `<div class="association-track-row" draggable="${mode==='fixed'?'true':'false'}" data-association-track="${esc(id)}"><span class="drag-handle">⠿</span><label class="checkline"><input type="checkbox" class="association-track" value="${esc(id)}" ${selectedSet.has(id)?'checked':''} ${mode==='dynamic'?'disabled':''}> ${esc(t.title)}</label><small>${esc(t.tags?.join('、')||'未分类')}</small></div>`;}).join('')||'<p class="muted">音乐馆中还没有曲目。</p>'}`;
  root.classList.toggle('disabled-choice',mode==='dynamic');
  $$('[data-association-track]',root).forEach(row=>{row.addEventListener('dragstart',e=>{if(form.elements.mode.value==='dynamic'){e.preventDefault();return;}row.classList.add('dragging');e.dataTransfer.setData('text/plain',row.dataset.associationTrack);});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.addEventListener('dragover',e=>{if(form.elements.mode.value==='fixed')e.preventDefault();});row.addEventListener('drop',e=>{if(form.elements.mode.value!=='fixed')return;e.preventDefault();const from=e.dataTransfer.getData('text/plain'),to=row.dataset.associationTrack;if(!from||from===to)return;const a=$(`[data-association-track="${CSS.escape(from)}"]`,root);if(!a)return;const nodes=$$('[data-association-track]',root),oldIndex=nodes.indexOf(a),newIndex=nodes.indexOf(row);if(oldIndex<newIndex)row.after(a);else row.before(a);});});
}
$('#associationForm').elements.mode.addEventListener('change',()=>{const f=$('#associationForm'),pl=state.playlists.find(p=>p.id===f.elements.playlistId.value),selected=$$('.association-track:checked').map(x=>x.value);if(f.elements.mode.value==='fixed'&&!selected.length&&f.elements.override.value==='custom')renderAssociationTracks(pl?.trackIds||[],pl?.trackIds||[]);else renderAssociationTracks(selected,selected.length?selected:(pl?.trackIds||[]));});
$('#associationForm').elements.playlistId.addEventListener('change',()=>{const f=$('#associationForm'),pl=state.playlists.find(p=>p.id===f.elements.playlistId.value);if(f.elements.mode.value==='fixed'&&f.elements.override.value==='custom')renderAssociationTracks(pl?.trackIds||[],pl?.trackIds||[]);else renderAssociationTracks([],pl?.trackIds||[]);});
