function parentMusicChoices(type,id){return type==='story'?'story':type;}
function applyStoryMusic(st,fromUserGesture=false){
  if(!st)return;const previousStoryId=state.player.storyId;const cfg=resolveMusicForStory(st);const currentId=state.player.trackId;
  if(cfg.off){stopAudio();state.player.storyId=st.id;state.player.playlistId='';currentQueue=[];currentQueueStoryId=st.id;return;}
  currentQueue=[...cfg.trackIds];currentQueueStoryId=st.id;currentLoop=cfg.loop||'list';state.player.storyId=st.id;state.player.playlistId=cfg.playlistId||'';
  if(!currentQueue.length){if(state.player.trackId||!audio.paused)stopAudio();state.player.storyId=st.id;state.player.playlistId='';state.player.queueTrackIds=[];state.player.trackId='';state.player.isPlaying=false;currentQueue=[];currentQueueStoryId=st.id;persist('');return;}
  if(currentId&&currentQueue.includes(currentId)&&!audio.paused){state.player.storyId=st.id;state.player.queueTrackIds=currentQueue;persist('');return;}
  const wasPlaying=!audio.paused&&!!currentId;
  if(wasPlaying||cfg.autoPlay||fromUserGesture&&cfg.autoPlay){const next=currentQueue[0];if(next)playTrack(next,{queue:currentQueue,storyId:st.id,loop:currentLoop});}
  else{state.player.queueTrackIds=currentQueue;persist('');}
}
async function trackUrl(t){if(!t)return '';if(t.kind==='url')return safeUrl(t.url)||'';if(t.mediaId){const u=await getMediaURL(t.mediaId);return u;}return '';}
async function playTrack(id,options={}){
  const t=state.tracks.find(x=>x.id===id);if(!t){toast('找不到这首音乐');return;}const queue=options.queue||currentQueue||[id];if(audio&&!audio.paused&&state.player.trackId===id){if(options.storyId)state.player.storyId=options.storyId;currentQueue=[...queue];currentLoop=options.loop||currentLoop;state.player.queueTrackIds=currentQueue;showPlayer(t);persist('');return;}
  const url=await trackUrl(t);if(!url){toast(t.kind==='file'?'这首本地音频缺少媒体文件，请从备份恢复或重新导入。':'网络音频地址无效');return;}
  audio.pause();audio.src=url;if(url.startsWith('blob:'))currentAudioObjectUrl=url;
  state.player.trackId=id;state.player.isPlaying=false;state.player.position=0;if(options.storyId)state.player.storyId=options.storyId;if(options.playlistId)state.player.playlistId=options.playlistId;
  currentQueue=[...queue];currentQueueStoryId=options.storyId||state.player.storyId||'';currentLoop=options.loop||currentLoop||'list';state.player.queueTrackIds=currentQueue;state.player.loop=currentLoop;
  try{await audio.play();state.player.isPlaying=true;lastAudioTrackId=id;showPlayer(t);await persist('开始播放：'+t.title);}catch(err){state.player.isPlaying=false;showPlayer(t);toast('浏览器未允许自动播放，或音频链接不可播放。请在播放器中点播放重试。');}
}
function stopAudio(){audio.pause();state.player.isPlaying=false;state.player.position=audio.currentTime||0;state.player.trackId='';state.player.queueTrackIds=[];state.player.playlistId='';currentQueue=[];currentQueueStoryId='';audio.removeAttribute('src');audio.load();renderPlayer();persist('');}
function stepTrack(dir){const q=currentQueue.length?currentQueue:state.player.queueTrackIds||[];let idx=q.indexOf(state.player.trackId);if(idx<0)idx=dir>0?-1:q.length;let next=idx+dir;if(next<0)next=currentLoop==='list'?q.length-1:0;if(next>=q.length){if(currentLoop==='list')next=0;else return;}if(q[next])playTrack(q[next],{queue:q,storyId:state.player.storyId,loop:currentLoop,playlistId:state.player.playlistId});}
function showPlayer(t){let p=$('#playerPanel');if(!p){p=document.createElement('div');p.id='playerPanel';p.className='player-panel';document.body.append(p);}p.hidden=false;p.innerHTML=`<h3>${esc(t?.title||'音乐播放器')}</h3><div class="muted">${esc(t?.kind==='url'?'网络音频':'已保存的本地音频')} · ${currentQueue.length?`${currentQueue.length} 首队列`:'独立试听'}</div><div class="player-controls"><button data-player="prev" aria-label="上一首">|◀</button><button class="play" data-player="toggle" aria-label="播放或暂停">${audio.paused?'▶':'Ⅱ'}</button><button data-player="next" aria-label="下一首">▶|</button></div><input type="range" id="playerSeek" min="0" max="100" value="0" aria-label="播放进度"><div class="audio-status">${esc(currentLoop==='list'?'当前队列循环播放':'当前队列播放完停止')}</div><div class="player-controls"><label>音量 <input type="range" id="playerVolume" min="0" max="1" step="0.05" value="${audio.volume}"></label><button class="text-button" id="closePlayer">收起</button></div>`;
  p.querySelector('[data-player=toggle]').onclick=async()=>{if(audio.paused){const active=state.tracks.find(x=>x.id===state.player.trackId)||t;if(active&&!audio.getAttribute('src')){const q=currentQueue.length?currentQueue:(state.player.queueTrackIds?.length?state.player.queueTrackIds:[active.id]);await playTrack(active.id,{queue:q,storyId:currentQueueStoryId||state.player.storyId,loop:state.player.loop||currentLoop,playlistId:state.player.playlistId});return;}try{await audio.play();state.player.isPlaying=true;await persist('');}catch{toast('播放失败，请检查音频地址或媒体是否可用。');}renderPlayer();showPlayer(state.tracks.find(x=>x.id===state.player.trackId)||t);}else{audio.pause();state.player.isPlaying=false;renderPlayer();showPlayer(t);}};
  p.querySelector('[data-player=prev]').onclick=()=>stepTrack(-1);p.querySelector('[data-player=next]').onclick=()=>stepTrack(1);p.querySelector('#closePlayer').onclick=()=>{p.hidden=true;};p.querySelector('#playerSeek').oninput=e=>{if(Number.isFinite(audio.duration)&&audio.duration>0)audio.currentTime=audio.duration*Number(e.target.value)/100;};p.querySelector('#playerVolume').oninput=e=>{audio.volume=Number(e.target.value);};updatePlayerProgress();
}
function renderPlayer(){const p=$('#playerPanel');if(p){const b=p.querySelector('[data-player=toggle]');if(b)b.textContent=audio.paused?'▶':'Ⅱ';}}
function updatePlayerProgress(){const p=$('#playerPanel');if(!p)return;const r=$('#playerSeek',p);if(r&&Number.isFinite(audio.duration)&&audio.duration>0)r.value=String(audio.currentTime/audio.duration*100);}
audio.addEventListener('timeupdate',()=>{state.player.position=audio.currentTime||0;updatePlayerProgress();});audio.addEventListener('play',()=>{state.player.isPlaying=true;renderPlayer();});audio.addEventListener('pause',()=>{state.player.isPlaying=false;renderPlayer();});audio.addEventListener('ended',()=>{const q=currentQueue.length?currentQueue:state.player.queueTrackIds||[];const i=q.indexOf(state.player.trackId);if(i>=0&&i<q.length-1){playTrack(q[i+1],{queue:q,storyId:currentQueueStoryId||state.player.storyId,loop:currentLoop,playlistId:state.player.playlistId});}else if(currentLoop==='list'&&q.length){playTrack(q[0],{queue:q,storyId:currentQueueStoryId||state.player.storyId,loop:currentLoop,playlistId:state.player.playlistId});}else{state.player.isPlaying=false;persist('');renderPlayer();}});
