function renderPlaylistTrackList(order){const root=$('#playlistTrackList');const ids=new Set(order||[]);const list=[...(order||[]).map(id=>state.tracks.find(t=>t.id===id)).filter(Boolean),...state.tracks.filter(t=>!ids.has(t.id))];root.innerHTML=list.map(t=>`<div class="playlist-track-row" draggable="true" data-playlist-track="${esc(t.id)}"><span class="drag-handle">⠿</span><label class="checkline"><input type="checkbox" value="${esc(t.id)}" ${ids.has(t.id)?'checked':''}> ${esc(t.title)}</label><small>${esc(t.kind==='file'?'本地':'网络')}</small></div>`).join('')||'<p class="muted">请先向音乐馆添加曲目。</p>';$$('[data-playlist-track]',root).forEach(row=>{row.addEventListener('dragstart',e=>{row.classList.add('dragging');e.dataTransfer.setData('text/plain',row.dataset.playlistTrack);});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.addEventListener('dragover',e=>{e.preventDefault();});row.addEventListener('drop',e=>{e.preventDefault();const from=e.dataTransfer.getData('text/plain'),to=row.dataset.playlistTrack;if(!from||from===to)return;const a=$(`[data-playlist-track="${CSS.escape(from)}"]`,root),b=row;if(a&&b){const nodes=$$('[data-playlist-track]',root),oldIdx=nodes.indexOf(a),newIdx=nodes.indexOf(b);if(oldIdx<newIdx)b.after(a);else b.before(a);autoSavePlaylistOrder();}});});root.onchange=e=>{if(e.target.matches('input[type=checkbox]'))autoSavePlaylistOrder();};}
